@import "@fontsource-variable/arimo";

/* Light (faithful): white news bands (#fff), near-white cards and footer (#f8f8f8), the light
   product band (#ececec), the mid-grey hero and mission band (#d9d9d9), warm near-black text
   (#454343), black nav and button labels, pale grey hairlines and quiet text (#aeaeae), and
   one amber (#f2a500) for the display word, hotspots and hovers. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.385 0.003 17.3);
  --card: oklch(0.979 0 0);
  --card-foreground: oklch(0 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.385 0.003 17.3);
  --primary: oklch(0.778 0.164 75.4);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.885 0 0);
  --secondary-foreground: oklch(0 0 0);
  --muted: oklch(0.943 0 0);
  --muted-foreground: oklch(0.751 0 0);
  --accent: oklch(0.778 0.164 75.4);
  --accent-foreground: oklch(0 0 0);
  --destructive: oklch(0.577 0.215 27.3);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.751 0 0);
  --input: oklch(0.751 0 0);
  --ring: oklch(0.778 0.164 75.4);
  --highlight: oklch(0.778 0.164 75.4);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(1 0 0);
  --chart-1: oklch(0.778 0.164 75.4);
  --chart-2: oklch(0.385 0.003 17.3);
  --chart-3: oklch(0.559 0 0);
  --chart-4: oklch(0.751 0 0);
  --chart-5: oklch(0.698 0.147 76.1);
  --sidebar: oklch(0.979 0 0);
  --sidebar-foreground: oklch(0.385 0.003 17.3);
  --sidebar-primary: oklch(0.778 0.164 75.4);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.943 0 0);
  --sidebar-accent-foreground: oklch(0 0 0);
  --sidebar-border: oklch(0.751 0 0);
  --sidebar-ring: oklch(0.778 0.164 75.4);

  --typeface-body: "Arimo Variable", Arimo, "Helvetica Neue", Helvetica, Arial, sans-serif;
  --typeface-display: "Arimo Variable", Arimo, "Helvetica Neue", Helvetica, Arial, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0rem;
  --page-width: 90rem;
  --page-gutter: clamp(1.25rem, 5.24vw - 0.03rem, 4.6875rem);
  --section-y: clamp(2.25rem, 1.35rem + 3.71vw, 4.6875rem);
}

/* Dark sibling: graphite bands in the same four steps (#141414 page, #1c1c1c cards, #202020
   product band, #262626 hero and mission band), light grey text, white labels, the same amber. */
.dark {
  --background: oklch(0.191 0 0);
  --foreground: oklch(0.831 0.002 17.2);
  --card: oklch(0.226 0 0);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.226 0 0);
  --popover-foreground: oklch(0.831 0.002 17.2);
  --primary: oklch(0.778 0.164 75.4);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.269 0 0);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.244 0 0);
  --muted-foreground: oklch(0.559 0 0);
  --accent: oklch(0.778 0.164 75.4);
  --accent-foreground: oklch(0 0 0);
  --destructive: oklch(0.65 0.2 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.475 0 0);
  --input: oklch(0.475 0 0);
  --ring: oklch(0.778 0.164 75.4);
  --highlight: oklch(0.828 0.166 79.4);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.475 0 0);
  --chart-1: oklch(0.778 0.164 75.4);
  --chart-2: oklch(0.831 0.002 17.2);
  --chart-3: oklch(0.633 0 0);
  --chart-4: oklch(0.475 0 0);
  --chart-5: oklch(0.698 0.147 76.1);
  --sidebar: oklch(0.226 0 0);
  --sidebar-foreground: oklch(0.831 0.002 17.2);
  --sidebar-primary: oklch(0.778 0.164 75.4);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.269 0 0);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(0.475 0 0);
  --sidebar-ring: oklch(0.778 0.164 75.4);
}
